onClick:
{{
  (() => {
    // 1. LUCCHETTO CHIUSO? Esco.
    if (appsmith.store.is_running) return;

    // 2. CHIUDO IL LUCCHETTO (Il tasto diventa grigio per sempre)
    storeValue('is_running', true);

    // ... CONTROLLI ...
    if (Table2.selectedRows.length === 0) {
        storeValue('proc_status', '⛔ ERRORE: Nessun articolo selezionato.');
        showAlert('Seleziona articoli', 'warning');
        storeValue('is_running', false); // RIAPRO SUBITO (Errore utente)
        return;
    }

    if (!Input_NewDescription.text) {
        storeValue('proc_status', '⛔ ERRORE: Manca descrizione.');
        showAlert('Manca descrizione', 'warning');
        storeValue('is_running', false); // RIAPRO SUBITO (Errore utente)
        return;
    }

    // ... ESECUZIONE ...
    storeValue('proc_status', '⚙️ Creazione in corso...');

    execute_copy_pack.run()
        .then((response) => {
            const nuovoID = response[0].NewPackID; 

            storeValue('proc_status', '✅ SUCCESSO! Creato ID: ' + nuovoID + '. CHIUDI LA FINESTRA.');
            showAlert('Pacchetto ' + nuovoID + ' creato!', 'success');

            get_invoice_packs.run(); 
            resetWidget('Input_NewDescription');

            // --- ATTENZIONE: QUI HO TOLTO LA RIGA storeValue('is_running', false) ---
            // Il bottone rimarrà grigio (disabilitato) finché non chiudi il modale.
        })
        .catch((err) => {
            storeValue('proc_status', '❌ ERRORE: ' + err.message);
            showAlert('Errore: ' + err.message, 'error');

            // QUI INVECE DEVI RIAPRIRE: Se c'è errore tecnico, devo poter riprovare
            storeValue('is_running', false);
        });
  })()
}}
